224	The following theorem records the self-testing (rigidity) properties of the Magic Square game. It is used in the soundness analysis of the Pauli basis test to enforce anticommutation relations between certain pairs of observables.
225	With zero-based labels, the paper's variables $1$ and $5$ have labels $0$ and
226	$4$, respectively.
227	
228	\begin{theorem}[Rigidity of the Magic Square game]\label{thm:ms-rigidity}
229		\lean{MIPStarRE.QPBT.exists_ms_rigidity}
230		\leanok
231		\uses{def:ms-game, def:tensor-product-value, def:EPR, def:povm-distance}
232		Let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy that succeeds in the Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ with probability $1-\eps$, where $\ket{\psi} \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$. Then there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\hilb_{\mathrm A'}, \hilb_{\mathrm B'} \cong (\C^2)^{\ot 2}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''}$ are finite dimensional, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A''} \ot \hilb_{\mathrm B''}$, such that:
233		\begin{enumerate}
234			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket{\psi} - \ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}} \bigr\| \le O(\sqrt\eps)$;
235			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$,
236			\begin{align*}
237				\tilde A^{\mathsf{Variable}_1}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^X_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
238				\tilde A^{\mathsf{Variable}_5}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^Z_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
239				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^X_b)_{\mathrm B'}\;,\\
240				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^Z_b)_{\mathrm B'}\;,
241			\end{align*}
242			where each $\approx_{\sqrt\eps}$ holds with respect to the state $\ket{\mathrm{EPR}_2}^{\ot 2}_{\mathrm{A'B'}} \ot \ket{\mathrm{aux}}_{\mathrm{A''B''}}$ and the answer summation is over $b \in \{0,1\}$, and the approximation bounds carry implicit universal constants.
243		\end{enumerate}
244		As a consequence, letting $\tilde A^{\mathsf{Variable}_1} = \tilde A^{\mathsf{Variable}_1}_0 - \tilde A^{\mathsf{Variable}_1}_1$ and $\tilde A^{\mathsf{Variable}_5} = \tilde A^{\mathsf{Variable}_5}_0 - \tilde A^{\mathsf{Variable}_5}_1$ denote the associated observables, it holds that
245		\begin{align*}
246			\tilde A^{\mathsf{Variable}_1} \tilde A^{\mathsf{Variable}_5} \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} -\, \tilde A^{\mathsf{Variable}_5} \tilde A^{\mathsf{Variable}_1} \ot I_{\mathrm{B'B''}}\;,\\
247			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1} \tilde B^{\mathsf{Variable}_5} &\approx_{\sqrt\eps} -\, I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5} \tilde B^{\mathsf{Variable}_1}\;,
248		\end{align*}
249		where, for operators $M$, $N$ that are not POVM elements, the notation $M \approx_\delta N$ means $\bra{\psi} (M-N)^\dagger (M-N) \ket{\psi} \le O(\delta)$ with respect to the same state.
250	\end{theorem}
251	\begin{proof}
252		This result is imported from Theorem~6.9 of~\cite{Coladangelo2017Robust}. There are two minor differences between their statement and the one given here. First, they state a robustness of $O(\eps)$, but measure the closeness of the actual and ideal states in trace norm; expressed as the Euclidean distance between $\phi_{\mathrm A} \ot \phi_{\mathrm B}\ket{\psi}$ and $\ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}}$, this becomes $O(\sqrt\eps)$. Second, their ideal observables for the $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ questions are $I \ot \sigma^Z$ and $\sigma^Z\sigma^X \ot \sigma^Z\sigma^X$; under a local change of basis these are equivalent to $\sigma^X \ot I$ and $\sigma^Z \ot I$, respectively.
253	\end{proof}
254	
255	The converse construction shows that any pair of anticommuting binary observables yields a perfect strategy for the Magic Square game.
256	
257	\begin{theorem}\label{thm:ms-from-ac}
258		\lean{MIPStarRE.QPBT.obsOf, MIPStarRE.QPBT.exists_ms_perfect_strategy_of_anticommuting}
259		\leanok
260		\uses{def:ms-game, def:consistent-measurement, def:spcc, def:EPR, def:tensor-product-value}
261		Let $A = \{A_b\}_{b \in \F_2}$ and $B = \{B_b\}_{b \in \F_2}$ be two-outcome projective measurements acting on $(\C^q)^{\ot n}$ that are consistent on $\ket{\mathrm{EPR}_q}^{\ot n}$ (Definition~\ref{def:consistent-measurement}), and let $\mathcal O_A = A_0 - A_1$ and $\mathcal O_B = B_0 - B_1$ be the corresponding $\pm 1$-valued observables. Suppose that $\mathcal O_A \mathcal O_B = - \mathcal O_B \mathcal O_A$. Then there exists a symmetric strategy $\mathcal S = (\psi, M)$ for the Magic Square game with the following properties:
262		\begin{enumerate}
263			\item $\mathcal S$ is an SPCC (symmetric, projective, consistent, commuting) strategy of value $1$;
264			\item the state is $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$;
265			\item for $b \in \{0,1\}$, $M^{\mathsf{Variable}_1}_b = A_b \ot I$ and $M^{\mathsf{Variable}_5}_b = B_b \ot I$.
266		\end{enumerate}
267	\end{theorem}
268	\begin{proof}
269		\uses{def:consistent-measurement}
270		The strategy is based on the canonical two-qubit operator solution of the Magic Square, with the state $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$ and the cells of the grid assigned the $\pm 1$-valued observables
271		\[
272			\begin{array}{ccc}
273				\mathcal O_A \ot I & I \ot \sigma^X & \mathcal O_A \ot \sigma^X \\[2pt]
274				I \ot \sigma^Z & \mathcal O_B \ot I & \mathcal O_B \ot \sigma^Z \\[2pt]
275				\mathcal O_A \ot \sigma^Z & \mathcal O_B \ot \sigma^X & \mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X
276			\end{array}
277		\]
278		on $(\C^q)^{\ot n} \ot \C^2$: on question $\mathsf{Variable}_j$ a player measures the two-outcome projective measurement of the observable in cell $j$, and on question $\mathsf{Constraint}_i$ a player simultaneously performs the three measurements of the corresponding row or column; item~3 holds by construction. Anticommutation of $\mathcal O_A$ and $\mathcal O_B$ gives
279		\begin{equation}\label{eq:am-i-hermitian}
280			\mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X
281			= - \mathcal O_A \mathcal O_B \ot \sigma^X \sigma^Z
282			= \mathcal O_B \mathcal O_A \ot \sigma^X \sigma^Z
283			= (\mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X)^\dagger\;,
284		\end{equation}
285		so the bottom-right cell is Hermitian, and it squares to the identity; hence every cell is a genuine $\pm 1$-valued observable. The three observables in each row and each column commute pairwise --- for the third row and third column this again uses Equation~\eqref{eq:am-i-hermitian} --- so the $\mathsf{Constraint}$ measurements are well defined, and the strategy is symmetric, projective, and commuting. A two-outcome projective measurement is consistent on a state if and only if its observable $\mathcal O$ satisfies $\mathcal O \ot I \ket{\psi} = I \ot \mathcal O \ket{\psi}$; since $A$ and $B$ are consistent on $\ket{\mathrm{EPR}_q}^{\ot n}$ by hypothesis and $\sigma^X$, $\sigma^Z$ are consistent on $\ket{\mathrm{EPR}_2}$, each cell observable is a product of consistent, commuting factors and is therefore consistent on $\ket{\psi}$, and consistency of the $\mathsf{Constraint}$ measurements follows from the cellwise consistencies together with commutativity. Finally, the observables in each row and each of the first two columns multiply to $I$, while those of the third column multiply to $-I$; for the measurement $\{S_0, S_1\}$ obtained by measuring a $\mathsf{Constraint}_i$ triple and outputting the sum of the three bits, the observable $S_0 - S_1$ equals the product of the three cell observables, hence $\pm I$, which forces the three answer bits to sum to $0$ (respectively, $1$ for $\mathsf{Constraint}_6$) with certainty. Together with consistency this shows that every check of the Magic Square game is passed with probability $1$, so the strategy has value $1$.
286	\end{proof}
